def hybrid_hardened_obfuscate(plaintext, pins, rotors, notches, plugboard=None):
    """
    Universal ASCII obfuscation with Enigma-style mechanics.

    Args:
        plaintext: str to encrypt
        pins: list[int] - initial rotor positions, len must match rotors
        rotors: list[int] - rotor wiring offsets, used as additive shift
        notches: list[int] - notch positions that trigger next rotor to step
        plugboard: dict[str, str] - optional letter swaps, e.g. {'A':'Q', 'Q':'A'}

    DOMAIN_SIZE = 95 covers ' ' (32) through '~' (126)
    """
    DOMAIN_SIZE = 95
    START_CHAR = 32

    if len(pins)!= len(rotors) or len(rotors)!= len(notches):
        raise ValueError("pins, rotors, and notches must be same length")

    # Build plugboard map, default to identity
    if plugboard is None:
        plugboard = {}
    pb_map = {chr(i): chr(i) for i in range(START_CHAR, START_CHAR + DOMAIN_SIZE)}
    for k, v in plugboard.items():
        if START_CHAR <= ord(k) < START_CHAR + DOMAIN_SIZE and START_CHAR <= ord(v) < START_CHAR + DOMAIN_SIZE:
            pb_map[k] = v
            pb_map[v] = k # plugboard is reciprocal

    ciphertext = []
    rotor_positions = pins.copy()

    for char in plaintext:
        # 1. Pass through plugboard first
        char = pb_map.get(char, char)

        if START_CHAR <= ord(char) <= START_CHAR + DOMAIN_SIZE - 1:
            idx = ord(char) - START_CHAR

            # 2. Keystream from current rotor positions
            keystream_shift = sum(rotor_positions) % DOMAIN_SIZE

            # 3. Rotor wiring: pass through each rotor left-to-right
            shift = keystream_shift
            for r in range(len(rotors)):
                shift = (shift + rotors[r] + rotor_positions[r]) % DOMAIN_SIZE

            out_idx = (idx + shift) % DOMAIN_SIZE
            out_char = chr(out_idx + START_CHAR)

            # 4. Pass through plugboard again on the way out
            out_char = pb_map.get(out_char, out_char)
            ciphertext.append(out_char)

            # 5. Variable stepping with notch system
            # Rightmost rotor always steps
            step_next = True
            for r in reversed(range(len(rotors))):
                if step_next:
                    rotor_positions[r] = (rotor_positions[r] + 1) % DOMAIN_SIZE
                    # If this rotor hit its notch, the next rotor left will step too
                    step_next = (rotor_positions[r] == notches[r])
                else:
                    step_next = False
        else:
            # Non-printable: pass through unchanged
            ciphertext.append(char)

    return "".join(ciphertext)

