          border: "none", borderRadius: 4, padding: "8px 16px",
          fontFamily: "'Orbitron'", fontSize: "0.6rem", fontWeight: 700,
          color: "#fff", cursor: loading ? "not-allowed" : "pointer", letterSpacing: 2,
          transition: "all 0.2s"
        }}>
          {loading ? "..." : "SEND"}
        </button>
      </div>
    </Panel>
  );
}

