    border-radius: 8px;
    padding: 20px;
    margin-bottom: 16px;
  }

  .panel-title {
    font-family: var(--font-mono);
    font-size: 11px;
    letter-spacing: 3px;
    text-transform: uppercase;
    color: var(--elm-cyan);
    margin-bottom: 16px;
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .panel-title::after {
    content: '';
    flex: 1;
    height: 1px;
    background: var(--elm-border);
  }

  /* GRID */
  .grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
  .grid-3 { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 16px; }
  @media(max-width: 768px) { .grid-2, .grid-3 { grid-template-columns: 1fr; } }

  /* STAT CARDS */
  .stat-card {
    background: rgba(0,255,229,0.03);
    border: 1px solid var(--elm-border);
    border-radius: 6px;
    padding: 16px;
    display: flex;
    flex-direction: column;
    gap: 6px;
  }

  .stat-label {
    font-family: var(--font-mono);
    font-size: 9px;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: var(--elm-gray);
  }

  .stat-value {
    font-family: var(--font-mono);
    font-size: 22px;
    font-weight: 700;
    color: var(--elm-white);
  }

  .stat-value.cyan { color: var(--elm-cyan); }
  .stat-value.red { color: var(--elm-red); }
  .stat-value.yellow { color: var(--elm-yellow); }
  .stat-value.green { color: var(--elm-green); }

  .stat-sub {
    font-family: var(--font-mono);
    font-size: 9px;
    color: var(--elm-gray);
  }

  /* TICKET ITEMS */
  .ticket {
    background: var(--elm-dark);
    border: 1px solid var(--elm-border);
    border-radius: 6px;
    padding: 14px 16px;
    margin-bottom: 10px;
    display: flex;
    gap: 14px;
    align-items: flex-start;
  }

  .ticket-id {
    font-family: var(--font-mono);
    font-size: 10px;
    color: var(--elm-cyan);
    min-width: 110px;
  }

  .ticket-body { flex: 1; }

  .ticket-title {
    font-size: 13px;
    font-weight: 600;
    color: var(--elm-white);
    margin-bottom: 4px;
  }

  .ticket-desc {
    font-family: var(--font-mono);
    font-size: 10px;
    color: var(--elm-gray);
    line-height: 1.6;
  }

  .ticket-badges {
    display: flex;
    gap: 6px;
    margin-top: 8px;
    flex-wrap: wrap;
  }

  .badge {
    font-family: var(--font-mono);
    font-size: 9px;
    letter-spacing: 1px;
    padding: 2px 8px;
    border-radius: 3px;
    text-transform: uppercase;
  }

  .badge-crit { background: rgba(255,60,90,0.15); color: var(--elm-red); border: 1px solid var(--elm-red); }
  .badge-warn { background: rgba(255,215,0,0.1); color: var(--elm-yellow); border: 1px solid var(--elm-yellow); }
  .badge-info { background: rgba(0,255,229,0.08); color: var(--elm-cyan); border: 1px solid var(--elm-cyan-dim); }
  .badge-ok   { background: rgba(0,255,136,0.08); color: var(--elm-green); border: 1px solid var(--elm-green); }
  .badge-dest { background: rgba(150,100,255,0.12); color: #b088ff; border: 1px solid #7a55cc; }

  /* LOG ENTRIES */
  .log-entry {
    font-family: var(--font-mono);
    font-size: 11px;
    line-height: 1.8;
    padding: 6px 0;
    border-bottom: 1px solid rgba(13,46,58,0.5);
    display: flex;
    gap: 12px;
  }

  .log-ts { color: var(--elm-gray); min-width: 175px; }
  .log-level { min-width: 55px; }
  .log-level.INFO { color: var(--elm-cyan); }
  .log-level.WARN { color: var(--elm-yellow); }
  .log-level.CRIT { color: var(--elm-red); }
  .log-level.VAULT { color: #b088ff; }
  .log-msg { color: var(--elm-text); flex: 1; }

  /* CONVERSATION BLOCKS */
  .conv-block {
    border-left: 3px solid var(--elm-border);
    padding: 10px 16px;
    margin-bottom: 12px;
    border-radius: 0 6px 6px 0;
    background: rgba(0,0,0,0.2);
  }

  .conv-block.user { border-left-color: var(--elm-cyan); }
  .conv-block.ai   { border-left-color: var(--elm-gray); }

  .conv-role {
    font-family: var(--font-mono);
    font-size: 9px;
    letter-spacing: 2px;
    text-transform: uppercase;
    margin-bottom: 6px;
  }

  .conv-block.user .conv-role { color: var(--elm-cyan); }
  .conv-block.ai .conv-role   { color: var(--elm-gray); }

  .conv-text {
    font-size: 12px;
    color: var(--elm-text);
    line-height: 1.7;
  }

  /* VAULT ENTRY */
  .vault-box {
    background: linear-gradient(135deg, rgba(176,136,255,0.05), rgba(0,255,229,0.03));
    border: 1px solid rgba(176,136,255,0.3);
    border-radius: 8px;
    padding: 20px;
    margin-bottom: 16px;
  }

  .vault-header {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 14px;
  }

  .vault-icon { font-size: 20px; }

  .vault-title {
    font-family: var(--font-mono);
    font-size: 13px;
    font-weight: 700;
    color: #b088ff;
    letter-spacing: 2px;
    text-transform: uppercase;
  }

  .vault-kv {
    display: grid;
    grid-template-columns: 160px 1fr;
    gap: 6px 12px;
    font-family: var(--font-mono);
    font-size: 11px;
  }

  .vault-key { color: var(--elm-gray); }
  .vault-val { color: var(--elm-white); }
  .vault-val.cyan { color: var(--elm-cyan); }
  .vault-val.green { color: var(--elm-green); }
  .vault-val.purple { color: #b088ff; }

  /* SECTION visibility */
  .section { display: none; }
  .section.active { display: block; }

  /* FOOTER */
  .footer {
    margin-top: 32px;
    border-top: 1px solid var(--elm-border);
    padding-top: 16px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 8px;
  }

  .footer-brand {
    font-family: var(--font-mono);
    font-size: 10px;
    color: var(--elm-gray);
  }

  .footer-lock {
    font-family: var(--font-mono);
    font-size: 10px;
    color: var(--elm-cyan);
    display: flex;
    align-items: center;
    gap: 6px;
  }

  /* Scrollbar */
  ::-webkit-scrollbar { width: 6px; height: 6px; }
  ::-webkit-scrollbar-track { background: var(--elm-dark); }
  ::-webkit-scrollbar-thumb { background: var(--elm-border); border-radius: 3px; }
</style>
