<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8"/>
<meta name="viewport" content="width=device-width, initial-scale=1.0"/>
<title>ELM369 | Conversation Archive & Security Diagnostic</title>
<link href="https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@300;400;600;700&family=Outfit:wght@300;400;600;700;900&display=swap" rel="stylesheet"/>
<style>
  :root {
    --elm-cyan: #00FFE5;
    --elm-cyan-dim: #00bfac;
    --elm-dark: #050d12;
    --elm-panel: #0a1a22;
    --elm-border: #0d2e3a;
    --elm-red: #ff3c5a;
    --elm-yellow: #ffd700;
    --elm-green: #00ff88;
    --elm-gray: #4a6470;
    --elm-text: #b0ccd6;
    --elm-white: #e8f4f8;
    --font-mono: 'JetBrains Mono', monospace;
    --font-ui: 'Outfit', sans-serif;
  }

  * { box-sizing: border-box; margin: 0; padding: 0; }

  body {
    background: var(--elm-dark);
    color: var(--elm-text);
    font-family: var(--font-ui);
    min-height: 100vh;
    overflow-x: hidden;
  }

  /* Background grid */
  body::before {
    content: '';
    position: fixed;
    inset: 0;
    background-image:
      linear-gradient(rgba(0,255,229,0.03) 1px, transparent 1px),
      linear-gradient(90deg, rgba(0,255,229,0.03) 1px, transparent 1px);
    background-size: 40px 40px;
    pointer-events: none;
    z-index: 0;
  }

  /* Scanline effect */
  body::after {
    content: '';
    position: fixed;
    inset: 0;
    background: repeating-linear-gradient(
      0deg,
      transparent,
      transparent 2px,
      rgba(0,0,0,0.08) 2px,
      rgba(0,0,0,0.08) 4px
    );
    pointer-events: none;
    z-index: 0;
  }

  .wrapper {
    position: relative;
    z-index: 1;
    max-width: 1280px;
    margin: 0 auto;
    padding: 20px;
  }

  /* HEADER */
  .header {
    border-bottom: 1px solid var(--elm-border);
    padding-bottom: 20px;
    margin-bottom: 24px;
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    flex-wrap: wrap;
    gap: 12px;
  }

  .header-brand {
    display: flex;
    flex-direction: column;
    gap: 4px;
  }

  .brand-label {
    font-family: var(--font-mono);
    font-size: 10px;
    color: var(--elm-cyan);
    letter-spacing: 4px;
    text-transform: uppercase;
  }

  .brand-title {
    font-family: var(--font-ui);
    font-size: 28px;
    font-weight: 900;
    color: var(--elm-white);
    letter-spacing: -0.5px;
  }

  .brand-title span { color: var(--elm-cyan); }

  .brand-sub {
    font-family: var(--font-mono);
    font-size: 11px;
    color: var(--elm-gray);
  }

  .header-meta {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 4px;
  }

  .status-pill {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    background: rgba(0,255,136,0.08);
    border: 1px solid var(--elm-green);
    border-radius: 100px;
    padding: 4px 12px;
    font-family: var(--font-mono);
    font-size: 10px;
    color: var(--elm-green);
    letter-spacing: 2px;
  }

  .status-pill::before {
    content: '';
    width: 6px; height: 6px;
    border-radius: 50%;
    background: var(--elm-green);
    animation: pulse 1.5s infinite;
  }

  @keyframes pulse {
    0%,100% { opacity: 1; }
    50% { opacity: 0.3; }
  }

  .meta-ts {
    font-family: var(--font-mono);
    font-size: 10px;
    color: var(--elm-gray);
  }

  .meta-loc {
    font-family: var(--font-mono);
    font-size: 10px;
    color: var(--elm-cyan);
  }

  /* LOCATION LOCK BANNER */
  .loc-banner {
    background: linear-gradient(90deg, rgba(0,255,229,0.06), transparent);
    border: 1px solid rgba(0,255,229,0.2);
    border-left: 3px solid var(--elm-cyan);
    border-radius: 6px;
    padding: 10px 16px;
