    setActiveHistory(null);

    const channelLabel = CHANNELS.find(c => c.id === channel)?.label;
    const toneLabel = TONES.find(t => t.id === tone)?.label;

    const userPrompt = `Channel: ${channelLabel}
Tone: ${toneLabel}
Incoming message / situation:
"${inputMsg}"

Generate a professional ${channelLabel} response now as Bo.`;

    try {
      const res = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          model: "claude-sonnet-4-20250514",
          max_tokens: 1000,
          system: SYSTEM_PROMPT,
          messages: [{ role: "user", content: userPrompt }],
        }),
      });
      const data = await res.json();
      const text = data.content?.map(b => b.text || "").join("") || "No response generated.";
      setResponse(text);
      setHistory(prev => [{
        id: Date.now(),
        channel,
        tone,
        input: inputMsg,
        output: text,
        timestamp: new Date().toLocaleString(),
      }, ...prev.slice(0, 9)]);
    } catch (e) {
      setResponse("Connection error. Please retry.");
    }
    setLoading(false);
  };

  const copyResponse = () => {
    navigator.clipboard.writeText(response);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const selectedTone = TONES.find(t => t.id === tone);

  return (
    <div style={{
      minHeight: "100vh",
      background: "#050A0F",
      color: "#E2EBF0",
      fontFamily: "'Courier New', monospace",
      position: "relative",
      overflow: "hidden",
    }}>
      {/* Grid background */}
      <div style={{
        position: "fixed", inset: 0, zIndex: 0,
        backgroundImage: `
          linear-gradient(rgba(0,229,200,0.03) 1px, transparent 1px),
          linear-gradient(90deg, rgba(0,229,200,0.03) 1px, transparent 1px)
        `,
        backgroundSize: "40px 40px",
        pointerEvents: "none",
      }} />

      {/* Glow orb top right */}
      <div style={{
        position: "fixed", top: "-15%", right: "-10%",
        width: "500px", height: "500px",
        background: "radial-gradient(circle, rgba(0,229,200,0.07) 0%, transparent 70%)",
        zIndex: 0, pointerEvents: "none",
      }} />

      {/* Glow orb bottom left */}
      <div style={{
        position: "fixed", bottom: "-15%", left: "-10%",
        width: "400px", height: "400px",
        background: "radial-gradient(circle, rgba(74,158,255,0.05) 0%, transparent 70%)",
        zIndex: 0, pointerEvents: "none",
      }} />

      <div style={{ position: "relative", zIndex: 1, maxWidth: "920px", margin: "0 auto", padding: "24px 16px" }}>

        {/* \u2500\u2500 HEADER \u2500\u2500 */}
        <div style={{
          display: "flex", alignItems: "center", justifyContent: "space-between",
          borderBottom: "1px solid rgba(0,229,200,0.18)",
          paddingBottom: "18px", marginBottom: "28px",
        }}>
          <div style={{ display: "flex", alignItems: "center", gap: "14px" }}>
            {/* Bo Avatar */}
            <div style={{
              width: "52px", height: "52px", borderRadius: "50%",
              background: "linear-gradient(135deg, #00E5C8, #4A9EFF)",
              display: "flex", alignItems: "center", justifyContent: "center",
              fontSize: "22px", fontWeight: "900", color: "#050A0F",
              boxShadow: "0 0 24px rgba(0,229,200,0.4)",
              letterSpacing: "-1px",
            }}>BO</div>
            <div>
              <div style={{ fontSize: "22px", fontWeight: "700", letterSpacing: "3px", color: "#00E5C8" }}>
                BO
              </div>
              <div style={{ fontSize: "10px", color: "#5A7A8A", letterSpacing: "2px" }}>
                COMMUNICATIONS ASSISTANT \u00b7 ELM369
              </div>
            </div>
          </div>

          <div style={{ textAlign: "right" }}>
            <div style={{
              fontSize: "9px", color: "#00E5C8", letterSpacing: "2px",
              animation: "pulse 3s ease-in-out infinite",
            }}>
              \u25cf {statusMsg}
            </div>
            <div style={{ fontSize: "9px", color: "#2A4A5A", marginTop: "4px", letterSpacing: "1px" }}>
              JMR0824197846902
            </div>
          </div>
        </div>

        {/* \u2500\u2500 CHANNEL SELECTOR \u2500\u2500 */}
        <div style={{ marginBottom: "20px" }}>
          <div style={{ fontSize: "9px", color: "#5A7A8A", letterSpacing: "3px", marginBottom: "10px" }}>
            CHANNEL
          </div>
          <div style={{ display: "flex", gap: "10px", flexWrap: "wrap" }}>
            {CHANNELS.map(ch => (
              <button
                key={ch.id}
                onClick={() => setChannel(ch.id)}
                style={{
                  padding: "10px 20px",
                  background: channel === ch.id
                    ? "rgba(0,229,200,0.12)"
                    : "rgba(255,255,255,0.03)",
                  border: channel === ch.id
                    ? "1px solid rgba(0,229,200,0.5)"
                    : "1px solid rgba(255,255,255,0.07)",
                  borderRadius: "6px",
                  color: channel === ch.id ? "#00E5C8" : "#6A8A9A",
                  cursor: "pointer",
                  fontSize: "11px",
                  letterSpacing: "2px",
                  fontFamily: "'Courier New', monospace",
                  transition: "all 0.2s",
                  display: "flex", alignItems: "center", gap: "8px",
                }}
              >
                <span>{ch.icon}</span> {ch.label.toUpperCase()}
              </button>
            ))}
          </div>
        </div>

        {/* \u2500\u2500 TONE SELECTOR \u2500\u2500 */}
        <div style={{ marginBottom: "24px" }}>
          <div style={{ fontSize: "9px", color: "#5A7A8A", letterSpacing: "3px", marginBottom: "10px" }}>
            TONE
          </div>
          <div style={{ display: "flex", gap: "10px", flexWrap: "wrap" }}>
            {TONES.map(t => (
              <button
                key={t.id}
                onClick={() => setTone(t.id)}
                style={{
                  padding: "10px 16px",
                  background: tone === t.id
                    ? `rgba(${t.id === "corporate" ? "0,229,200" : t.id === "government" ? "74,158,255" : t.id === "both" ? "167,139,250" : "245,158,11"},0.1)`
                    : "rgba(255,255,255,0.03)",
                  border: tone === t.id
                    ? `1px solid ${t.color}60`
                    : "1px solid rgba(255,255,255,0.07)",
                  borderRadius: "6px",
                  color: tone === t.id ? t.color : "#6A8A9A",
                  cursor: "pointer",
                  fontFamily: "'Courier New', monospace",
                  transition: "all 0.2s",
                  textAlign: "left",
                }}
              >
                <div style={{ fontSize: "10px", letterSpacing: "2px", fontWeight: "700" }}>{t.label.toUpperCase()}</div>
                <div style={{ fontSize: "9px", opacity: 0.6, marginTop: "2px" }}>{t.sub}</div>
              </button>
            ))}
          </div>
        </div>

        {/* \u2500\u2500 INPUT \u2500\u2500 */}
        <div style={{ marginBottom: "16px" }}>
          <div style={{ fontSize: "9px", color: "#5A7A8A", letterSpacing: "3px", marginBottom: "10px" }}>
            INCOMING MESSAGE / SITUATION
          </div>
          <textarea
            value={inputMsg}
            onChange={e => setInputMsg(e.target.value)}
            onKeyDown={e => { if (e.key === "Enter" && e.ctrlKey) generate(); }}
            placeholder={`Paste the incoming ${CHANNELS.find(c=>c.id===channel)?.label} message here, or describe the situation Bo should respond to...`}
            rows={5}
            style={{
              width: "100%",
              background: "rgba(255,255,255,0.03)",
              border: "1px solid rgba(0,229,200,0.15)",
              borderRadius: "8px",
              color: "#C8DDE8",
              fontFamily: "'Courier New', monospace",
              fontSize: "13px",
              padding: "14px",
              resize: "vertical",
              outline: "none",
              lineHeight: "1.7",
              boxSizing: "border-box",
            }}
          />
          <div style={{ fontSize: "9px", color: "#2A4A5A", marginTop: "6px", letterSpacing: "1px" }}>
            CTRL + ENTER TO GENERATE
          </div>
        </div>

        {/* \u2500\u2500 GENERATE BUTTON \u2500\u2500 */}
        <button
          onClick={generate}
          disabled={loading || !inputMsg.trim()}
          style={{
            width: "100%",
            padding: "15px",
            background: loading
              ? "rgba(0,229,200,0.05)"
              : "linear-gradient(135deg, rgba(0,229,200,0.15), rgba(74,158,255,0.1))",
            border: `1px solid ${loading ? "rgba(0,229,200,0.2)" : "rgba(0,229,200,0.4)"}`,
            borderRadius: "8px",
            color: loading ? "#2A6A5A" : "#00E5C8",
            cursor: loading ? "not-allowed" : "pointer",
            fontFamily: "'Courier New', monospace",
            fontSize: "12px",
            letterSpacing: "4px",
            fontWeight: "700",
            transition: "all 0.3s",
            marginBottom: "28px",
          }}
        >
          {loading ? "BO IS DRAFTING RESPONSE..." : `\u25b6 GENERATE ${CHANNELS.find(c=>c.id===channel)?.label.toUpperCase()} RESPONSE`}
        </button>

        {/* \u2500\u2500 RESPONSE \u2500\u2500 */}
        {response && (
          <div style={{
            background: "rgba(0,229,200,0.04)",
            border: "1px solid rgba(0,229,200,0.2)",
            borderRadius: "10px",
            padding: "20px",
            marginBottom: "28px",
            animation: "fadeIn 0.4s ease",
          }}>
            <div style={{
              display: "flex", justifyContent: "space-between", alignItems: "center",
              marginBottom: "16px",
            }}>
              <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
                <div style={{
                  width: "28px", height: "28px", borderRadius: "50%",
                  background: "linear-gradient(135deg, #00E5C8, #4A9EFF)",
                  display: "flex", alignItems: "center", justifyContent: "center",
                  fontSize: "10px", fontWeight: "900", color: "#050A0F",
                }}>BO</div>
                <div>
                  <div style={{ fontSize: "10px", color: "#00E5C8", letterSpacing: "2px" }}>BO \u00b7 RESPONSE READY</div>
                  <div style={{ fontSize: "9px", color: "#2A4A5A", letterSpacing: "1px" }}>
                    {CHANNELS.find(c=>c.id===channel)?.label} \u00b7 {TONES.find(t=>t.id===tone)?.label} Tone
                  </div>
                </div>
              </div>
              <button
                onClick={copyResponse}
                style={{
                  padding: "7px 14px",
                  background: copied ? "rgba(0,229,200,0.2)" : "rgba(255,255,255,0.05)",
                  border: "1px solid rgba(0,229,200,0.25)",
                  borderRadius: "5px",
                  color: copied ? "#00E5C8" : "#6A8A9A",
                  cursor: "pointer",
                  fontFamily: "'Courier New', monospace",
                  fontSize: "9px",
                  letterSpacing: "2px",
                }}
              >
                {copied ? "\u2713 COPIED" : "COPY"}
              </button>
            </div>
            <div style={{
              fontSize: "13px", lineHeight: "1.8", color: "#C8DDE8",
              whiteSpace: "pre-wrap", borderTop: "1px solid rgba(0,229,200,0.1)",
              paddingTop: "16px",
            }}>
              {response}
            </div>
          </div>
        )}

        {/* \u2500\u2500 HISTORY \u2500\u2500 */}
        {history.length > 0 && (
          <div>
            <div style={{ fontSize: "9px", color: "#5A7A8A", letterSpacing: "3px", marginBottom: "12px" }}>
              SESSION LOG \u2014 {history.length} ENTR{history.length === 1 ? "Y" : "IES"}
            </div>
            <div style={{ display: "flex", flexDirection: "column", gap: "8px" }}>
              {history.map((item, i) => (
                <div
                  key={item.id}
                  onClick={() => setActiveHistory(activeHistory === item.id ? null : item.id)}
                  style={{
                    background: "rgba(255,255,255,0.02)",
                    border: "1px solid rgba(255,255,255,0.06)",
                    borderRadius: "8px",
                    padding: "12px 16px",
                    cursor: "pointer",
                    transition: "all 0.2s",
                  }}
                >
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                    <div style={{ display: "flex", gap: "10px", alignItems: "center" }}>
                      <span style={{ fontSize: "10px" }}>
                        {CHANNELS.find(c => c.id === item.channel)?.icon}
                      </span>
                      <span style={{ fontSize: "9px", color: "#00E5C8", letterSpacing: "1px" }}>
                        {CHANNELS.find(c => c.id === item.channel)?.label.toUpperCase()}
                      </span>
                      <span style={{ fontSize: "9px", color: "#4A6A7A", letterSpacing: "1px" }}>
                        {TONES.find(t => t.id === item.tone)?.label.toUpperCase()}
                      </span>
                    </div>
                    <span style={{ fontSize: "9px", color: "#2A4A5A" }}>{item.timestamp}</span>
                  </div>
                  <div style={{
                    fontSize: "11px", color: "#6A8A9A", marginTop: "6px",
                    overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap",
                  }}>
                    {item.input}
                  </div>
                  {activeHistory === item.id && (
                    <div style={{
                      marginTop: "12px", paddingTop: "12px",
                      borderTop: "1px solid rgba(0,229,200,0.1)",
                      fontSize: "12px", color: "#C8DDE8", lineHeight: "1.7",
                      whiteSpace: "pre-wrap",

ed4167f2-7f86-473c-b384-67799b1d1877.text:
GitHub issue #11: Project ELM369 Security & Integrated Architecture Dash Board. 

<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8"/>
<meta name="viewport" content="width=device-width, initial-scale=1.0"/>
<title>Project ELM369 · JMR0824197846902 · Pro Dashboard</title>
<link href="https://fonts.googleapis.com/css2?family=Share+Tech+Mono&family=Orbitron:wght@400;600;900&family=Rajdhani:wght@300;400;600&display=swap" rel="stylesheet"/>
<style>
  :root {
    --elm-cyan: #00f5d4;
    --elm-cyan2: #00c4aa;
    --elm-dark: #050d12;
    --elm-panel: #080f16;
    --elm-border: #0a2a35;
    --elm-red: #ff3860;
    --elm-yellow: #ffd166;
    --elm-green: #06d6a0;
    --elm-blue: #118ab2;
    --elm-glow: 0 0 12px #00f5d466;
    --elm-glow-red: 0 0 12px #ff386066;
    --font-mono: 'Share Tech Mono', monospace;
    --font-display: 'Orbitron', sans-serif;
    --font-body: 'Rajdhani', sans-serif;
  }

  * { box-sizing: border-box; margin: 0; padding: 0; }

  body {
    background: var(--elm-dark);
    color: #c0e8f0;
    font-family: var(--font-body);
    min-height: 100vh;
    overflow-x: hidden;
  }

  /* Scanline overlay */
  body::before {
    content: '';
    position: fixed;
    top: 0; left: 0; right: 0; bottom: 0;
    background: repeating-linear-gradient(
      0deg,
      transparent,
      transparent 2px,
      rgba(0,245,212,0.015) 2px,
      rgba(0,245,212,0.015) 4px
    );
    pointer-events: none;
    z-index: 9999;
  }

  /* Grid BG */
  body::after {
    content: '';
    position: fixed;
    top: 0; left: 0; right: 0; bottom: 0;
    background-image:
      linear-gradient(rgba(0,245,212,0.04) 1px, transparent 1px),
      linear-gradient(90deg, rgba(0,245,212,0.04) 1px, transparent 1px);
    background-size: 40px 40px;
    pointer-events: none;
    z-index: 0;
  }

  .wrap { position: relative; z-index: 1; padding: 16px; max-width: 900px; margin: 0 auto; }

  /* HEADER */
  .hdr {
    border-bottom: 1px solid var(--elm-cyan2);
    padding-bottom: 12px;
    margin-bottom: 20px;
    display: flex;
    flex-direction: column;
    gap: 4px;
  }
  .hdr-top {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 8px;
  }
  .hdr-title {
    font-family: var(--font-display);
    font-size: 1.3rem;
    font-weight: 900;
    color: var(--elm-cyan);
    text-shadow: var(--elm-glow);
    letter-spacing: 2px;
  }
  .hdr-title span { color: #fff; }
  .badge-pro {
    background: linear-gradient(135deg, #00f5d4, #118ab2);
    color: #000;
    font-family: var(--font-display);
    font-size: 0.6rem;
    font-weight: 900;
    padding: 3px 8px;
    border-radius: 3px;
    letter-spacing: 2px;
  }
  .hdr-meta {
    font-family: var(--font-mono);
    font-size: 0.65rem;
    color: #4a8f99;
    display: flex;
    gap: 16px;
    flex-wrap: wrap;
  }
  .hdr-meta span { color: var(--elm-cyan2); }

  /* SCORE STRIP */
  .score-strip {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 10px;
    margin-bottom: 20px;
  }
  .score-card {
    background: var(--elm-panel);
    border: 1px solid var(--elm-border);
    border-radius: 6px;
    padding: 12px 10px;
    text-align: center;
    position: relative;
    overflow: hidden;
    transition: border-color 0.2s;
  }
  .score-card:hover { border-color: var(--elm-cyan2); }
  .score-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
  }
  .score-card.ok::before { background: var(--elm-green); }
  .score-card.warn::before { background: var(--elm-yellow); }
  .score-card.crit::before { background: var(--elm-red); }
  .score-card.info::before { background: var(--elm-blue); }
  .score-num {
    font-family: var(--font-display);
    font-size: 1.6rem;
    font-weight: 900;
    line-height: 1;
    margin-bottom: 4px;
  }
  .score-card.ok .score-num { color: var(--elm-green); }
  .score-card.warn .score-num { color: var(--elm-yellow); }
  .score-card.crit .score-num { color: var(--elm-red); }
  .score-card.info .score-num { color: var(--elm-blue); }
  .score-label {
    font-family: var(--font-mono);
    font-size: 0.58rem;
    color: #4a8f99;
    text-transform: uppercase;
    letter-spacing: 1px;
  }

  /* SECTION */
  .section {
    background: var(--elm-panel);
    border: 1px solid var(--elm-border);
    border-radius: 8px;
    margin-bottom: 16px;
    overflow: hidden;
  }
  .section-hdr {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 10px 14px;
    border-bottom: 1px solid var(--elm-border);
    cursor: pointer;
    user-select: none;
    transition: background 0.15s;
  }
  .section-hdr:hover { background: rgba(0,245,212,0.04); }
  .section-hdr-left {
    display: flex;
    align-items: center;
    gap: 10px;
  }
  .section-icon {
    width: 28px;
    height: 28px;
    border-radius: 4px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.9rem;
  }
  .section-title {
    font-family: var(--font-display);
    font-size: 0.72rem;
    font-weight: 600;
    color: var(--elm-cyan);
    letter-spacing: 1.5px;
    text-transform: uppercase;
  }
  .section-sub {
    font-family: var(--font-mono);
    font-size: 0.6rem;
    color: #4a8f99;
    margin-top: 2px;
  }
  .section-toggle {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    color: var(--elm-cyan2);
    transition: transform 0.2s;
  }
  .section-toggle.open { transform: rotate(180deg); }
  .section-body { padding: 14px; display: none; }
  .section-body.open { display: block; }

  /* DEVICE GRID */
  .device-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
    gap: 10px;
    margin-bottom: 12px;
  }
  .device-card {
    background: #060d14;
    border: 1px solid var(--elm-border);
    border-radius: 6px;
    padding: 12px;
    position: relative;
  }
  .device-name {
    font-family: var(--font-display);
    font-size: 0.7rem;
    color: #fff;
    margin-bottom: 6px;
    letter-spacing: 1px;
  }
  .device-type {
    font-family: var(--font-mono);
    font-size: 0.58rem;
    color: #4a8f99;
    margin-bottom: 10px;
    text-transform: uppercase;
  }
  .device-bar-wrap {
    height: 4px;
    background: #0a2030;
    border-radius: 2px;
    margin-bottom: 6px;
    overflow: hidden;
  }
  .device-bar {
    height: 100%;
    border-radius: 2px;
    transition: width 1s ease;
  }
  .device-score-label {
    font-family: var(--font-mono);
    font-size: 0.6rem;
    display: flex;
    justify-content: space-between;
  }
  .device-status {
    position: absolute;
    top: 10px; right: 10px;
    width: 8px; height: 8px;
    border-radius: 50%;
    animation: pulse 2s infinite;
  }
  @keyframes pulse {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.3; }
  }

  /* TICKET TABLE */
  .ticket-table { width: 100%; border-collapse: collapse; }
  .ticket-table th {
    font-family: var(--font-mono);
    font-size: 0.58rem;
    color: #4a8f99;
    text-transform: uppercase;
    letter-spacing: 1px;
    text-align: left;
    padding: 6px 8px;
    border-bottom: 1px solid var(--elm-border);
  }
  .ticket-table td {
    font-family: var(--font-mono);
    font-size: 0.62rem;
    padding: 8px;
    border-bottom: 1px solid #0a1a22;
    vertical-align: top;
  }
  .ticket-table tr:hover td { background: rgba(0,245,212,0.03); }
  .tid { color: var(--elm-cyan2); }
  .sev {
    display: inline-block;
    padding: 2px 6px;
    border-radius: 3px;
    font-size: 0.55rem;
    font-weight: 700;
    letter-spacing: 1px;
    text-transform: uppercase;
  }
  .sev-crit { background: rgba(255,56,96,0.2); color: var(--elm-red); border: 1px solid var(--elm-red); }
  .sev-high { background: rgba(255,209,102,0.15); color: var(--elm-yellow); border: 1px solid var(--elm-yellow); }
  .sev-med { background: rgba(0,245,212,0.1); color: var(--elm-cyan); border: 1px solid var(--elm-cyan2); }
  .sev-low { background: rgba(6,214,160,0.1); color: var(--elm-green); border: 1px solid var(--elm-green); }
  .status-open { color: var(--elm-red); }
